def draw(T, li, e, f=0, seed=900, wind=0.):
    s = T.s; st = Stack(); c0 = T.c; box = (c0[0] - s * 2.2, c0[1] - s * 2.4, c0[0] + s * 2.2, c0[1] + s * 2.2); n = lambda sd: Part(T, box, sd); L = -1 if T.yaw >= -.05 else 1; k = -L; j = e['md'] * .22
    p = n(seed)                                             # hair back + topknot
    Kt = [(-.22, -1.10, -.1), (-.34 + wind * .1, -1.42, -.1), (-.20 + wind * .25, -1.70, -.1), (.14 + wind * .35, -1.76, -.1), (.36 + wind * .25, -1.52, -.1), (.24, -1.12, -.1)]; Q = p.shape(scallop(T.P3(spn(Kt, True, (), 8)), s * .26, s * .05, seed), C['hair'], 1.); p.line([(-.1, -1.2, 0), (-.1 + wind * .1, -1.5, 0), (.1 + wind * .2, -1.68, 0)], .45, '#5a5064'); p.line([(.08, -1.2, 0), (.14, -1.45, 0)], .4, '#5a5064'); p.shape([(-.22, -1.16, 0), (0, -1.22, .1), (.24, -1.16, 0), (.24, -1.04, 0), (0, -1.08, .1), (-.22, -1.04, 0)], C['gold'], .6)
    Hb = [(-.86, .02, 0), (-1.0, -.42, -.1), (-.84, -.86, -.1), (-.42, -1.14, -.1), (0, -1.20, -.1), (.42, -1.14, -.1), (.84, -.86, -.1), (1.0, -.42, -.1), (.86, .02, 0)]; Q = p.shape(Hb, C['hair'], 1., co=(0, 8)); st.add(p, li)
    p = n(seed + 20); NK = p.fill([(-.78, .5, -.1), (-.98, 1.06, -.1), (-1.30, 1.40, -.2), (0, 1.6, -.2), (1.30, 1.40, -.2), (.98, 1.06, -.1), (.78, .5, -.1)], C['skin'], co=(0, 6)); p.shade([(-1., .5, 0), (-.9, 1.16, 0), (-.2, 1.40, .1), (0, 1.7, 0), (1.5, 1.7, 0), (1., .5, 0)], C['sh'], NK); p.shade([(-.9, .6, 0), (-.6, 1.22, 0), (0, 1.32, .1), (.9, 1.30, 0), (.9, .6, 0)], C['dk'], NK); p.line([(-.84, .7, -.1), (-.99, 1.06, -.1), (-1.34, 1.36, -.2)], 1., taper=(.1, .5)); p.line([(.84, .7, -.1), (.99, 1.06, -.1), (1.34, 1.36, -.2)], 1., taper=(.1, .5))
    for sd in (-1, 1):                                       # gills
        for i in range(3): p.line([(sd * (.66 + .10 * i), .98 + .02 * i, .1), (sd * (.80 + .10 * i), 1.10, .1), (sd * (.78 + .10 * i), 1.30, .05)], .6)
    fc = [(-.40, -.94), (-.72, -.72), (-.84, -.34), (-.86, .04), (-.95, .40), (-.90, .74 + j * .5), (-.66, 1.0 + j), (-.28, 1.12 + j), (0, 1.13 + j), (.28, 1.12 + j), (.66, 1.0 + j), (.90, .74 + j * .5), (.95, .40), (.86, .04), (.84, -.34), (.72, -.72), (.40, -.94)]
    F = p.shape(fc, C['skin'], 1., limb=True)
    p.shade([(k * 1.0, -1.0), (k * .46, -.74), (k * .58, -.30), (k * .56, -.02), (k * .66, .28), (k * .58, .56), (k * .64, .78), (k * .34, 1.02 + j), (k * .06, 1.15 + j), (k * .5, 1.5), (k * 1.4, 1.2)], C['sh'], F); p.shade([(k * 1.1, .1), (k * .82, .26), (k * .80, .62), (k * .62, .96), (k * .3, 1.14 + j), (k * 1.2, 1.3)], C['dk'], F, .8)
    p.shade([(-.5, -.30), (-.24, -.16), (-.12, -.02), (-.18, .10), (-.42, .16), (-.62, .06)], C['sh'], F); p.shade([(.5, -.30), (.24, -.16), (.12, -.02), (.18, .10), (.42, .16), (.62, .06)], C['sh'], F)
    p.hl([(-k * .62, .26), (-k * .40, .18), (-k * .46, .36), (-k * .66, .42)], '#8fbbd8', .9, F); p.hl([(-k * .40, -.78), (-k * .10, -.82), (-k * .16, -.60), (-k * .46, -.56)], '#8fbbd8', .7, F)
    # whale-shark pale spots on the temple
    for x, y, r in ((-.62, -.40, .035), (-.70, -.24, .025), (-.54, -.52, .022), (.64, -.42, .035), (.72, -.26, .025), (.56, -.54, .022), (-.76, .20, .022), (.78, .20, .022)): p.f.fill(T(ell(x, y, r, r, 12)), C['belly'], .75)
    for sd in (-1, 1):
        eye(p, sd * .35, .0, .165, .125, e, sd, C['skin'], C['sh'], lidw=1.2); p.line([(sd * .18, .16), (sd * .34, .20), (sd * .52, .14)], .4); p.line([(sd * .20, .24), (sd * .36, .27), (sd * .48, .23)], .28)
    p.line([(-.07, -.20 + e['bi']), (-.05, -.06), (-.10, .04)], .5); p.line([(.07, -.20 + e['bi']), (.05, -.06), (.10, .04)], .5)
    if e['bi'] > .06: p.line([(-.30, -.52), (0, -.46), (.30, -.52)], .4); p.line([(-.22, -.62), (0, -.57), (.22, -.62)], .3)
    # scar over his left eye (viewer right), jagged
    Sx = spn([(.50, -.40), (.40, -.20), (.46, -.10), (.36, .10), (.44, .20), (.34, .44)], False, (1, 2, 3, 4), 4); p.f.line(T(Sx), s * .05, C['dk']); p.f.line(T(Sx) + [-s * .012, -s * .008], s * .022, C['belly']); p.line([tuple(v) for v in Sx[::2]], .3)
    # nose: broad
    N = [(-.06, -.02), (-.10, .12), (-.23, .28), (-.20, .38), (-.08, .40), (0, .43), (.08, .40), (.20, .38), (.23, .28), (.10, .12), (.06, -.02)]; Qn = p.T(spn(N, True, (), 8), None, .12); p.shade(Qn + [k * s * .08, s * .10], C['dk'], F, .75); p.f.fill(Qn, C['skin']); p.shade([(k * .03, -.1), (k * .06, .24), (k * .02, .44), (k * .4, .5), (k * .4, -.1)], C['sh'], Qn, dz=.12)
    p.line([(-.10, .10), (-.23, .27), (-.20, .37), (-.10, .385)], .6, dz=.12); p.line([(.10, .10), (.23, .27), (.20, .37), (.10, .385)], .6, dz=.12); p.line([(-.09, .395), (0, .43), (.09, .395)], .6, dz=.12); p.hl(ell(*T.at(-.05 * k, .26, .95), s * .03, s * .05, 12), '#b6d6e8', 1., Qn)
    p.line([(-.26, .34), (-.46, .50), (-.56, .68)], .5); p.line([(.26, .34), (.46, .50), (.56, .68)], .5)
    # mouth, underlip, tusks rising outside the lip
    my = .66; mouth(p, 0, my, e, w=1., inn='#2c0f1c')
    u = np.linspace(-1, 1, 13); lf = -e['ml'] * np.abs(u) ** 1.5; LL = T(np.r_[np.c_[(e['mw'] + .04) * u, my + lf + e['md'] * (1 - np.abs(u) ** 2.2) ** .8 + .0], np.c_[(e['mw'] + .02) * u, my + lf + (e['md'] + .115) * (1 - np.abs(u) ** 3)][::-1]]); p.fill(LL, C['lip']); p.shade(LL + [0, s * .06], C['sh'], LL); p.ol(LL, .55)
    for sd in (-1, 1):
        tx = sd * (e['mw'] * .72 + .02); ty = my - e['ml'] * .6 + e['md'] * .52; TK = [(tx - .085, ty + .05), (tx - .075 + sd * .01, ty - .10), (tx + sd * .06, ty - .34), (tx + .08 + sd * .015, ty - .08), (tx + .085, ty + .05)]; Q = p.shape(T(spn(TK, True, (0, 2, 4), 8), None, .08), C['tooth'], .75); p.shade([(tx + k * .01, ty + .1), (tx + sd * .06, ty - .36), (tx + k * .2, ty + .1)], C['toothS'], Q, dz=.08); p.shade([(tx - .1, ty - .02), (tx, ty + .02), (tx + .1, ty - .02), (tx + .1, ty + .1), (tx - .1, ty + .1)], C['gold'], Q, dz=.08)
    # goatee: gold tuft
    G = [(-.12, .98 + j), (0, .94 + j), (.12, .98 + j), (.10, 1.20 + j), (.02 + wind * .1, 1.42 + j), (-.10, 1.20 + j)]; Q = p.shape(T(spn(G, True, (0, 2, 4), 8), None, .14), C['gold'], .7); p.shade(Q + [k * s * .05, s * .02], C['goldS'], Q); p.line([(0, 1.02 + j), (.01, 1.3 + j)], .3)
    # front hairline + lightning sideburns ending in curls
    Hl = [(-.90, -.10, .2), (-.94, -.50, .1), (-.74, -.90, .2), (-.36, -1.12, .3), (0, -1.16, .4), (.36, -1.12, .3), (.74, -.90, .2), (.94, -.50, .1), (.90, -.10, .2), (.80, -.50, .3), (.62, -.80, .4), (.26, -.90, .52), (0, -.82, .6), (-.26, -.90, .52), (-.62, -.80, .4), (-.80, -.50, .3)]; Q = p.shape(Hl, C['hair'], .9, co=(0, 8, 12)); p.hl([(-.6, -.98, .3), (-.3, -1.06, .4), (.1, -1.06, .4), (-.1, -.98, .5), (-.4, -.94, .5)], C['hair2'], 1., Q); [p.line([(x, -1.12 + abs(x) * .2, .3), (x * .9, -.84 + abs(x) * .06, .6)], .35, '#564b60') for x in (-.5, -.3, -.1, .12, .32, .52)]
    for sd in (-1, 1):
        SB = [(sd * .86, -.24, .15), (sd * .72, .02, .40), (sd * .84, .04, .25), (sd * .70, .30, .42), (sd * .84, .30, .25), (sd * .78, .56, .35), (sd * .98, .62, .10), (sd * 1.10, .44, .0), (sd * 1.0, .30, .0), (sd * 1.04, .06, 0), (sd * .98, -.24, 0)]; Q = p.shape(SB, C['hair'], .7, co=(0, 1, 2, 3, 4, 5, 10), n=5)
        p.line([(sd * 1.02, .40, .1), (sd * .94, .46, .1), (sd * .92, .54, .1), (sd * 1.0, .56, .1)], .45, '#6a5f74')
    p.ticks((k * .52, .34), (k * .70, .62), 8, .28, .15); p.ticks((-k * .66, .40), (-k * .50, .52), 5, .24, .11)
    st.add(p, li); p = n(seed + 60)
    for sd in (-1, 1):
        # gold brow: thick, sweeping out into a curl
        bi, bo = e['bi'], e['bo']; B = band_poly(T(spn([(sd * .12, -.16 + bi), (sd * .30, -.30 + bi * .4), (sd * .56, -.34 + bo), (sd * .80, -.50 + bo), (sd * .92, -.72 + bo), (sd * .80, -.86 + bo), (sd * .68, -.76 + bo), (sd * .74, -.66 + bo)], False, (), 10)), [s * v for v in (.10, .17, .17, .14, .11, .10, .08, .03)]); p.shape(B, C['gold'], .7); p.shade(B + [0, s * .055], C['goldS'], B)
    st.add(p, li); return st.a


def head(cx, cy, s, yaw=0., pitch=0., roll=0., expr='calm', light_='day', f=0, **kw):
    li = kw.pop('light', light_); li = light(li) if isinstance(li, str) else li; sq = kw.pop('sq', (1., 1.))
    return draw(Rig(cx, cy, s, yaw, pitch, roll, kw.pop('persp', .12), r=(.92, 1.14, .84), sx=sq[0], sy=sq[1]), li, pick(EX, expr), f, **kw)


def sunmark(cx, cy, R, rot=0., sq=(1., 1.)):
    """Sun Pirates mark: disc + curved rays -> list of polys"""
    out = [ell(0, 0, R * .40, R * .40, 28)]
    for i in range(8):
        a = i * math.pi / 4; c, s_ = math.cos(a), math.sin(a); P = [(R * .46, -R * .13), (R * .74, -R * .16), (R * 1.0, R * .02), (R * .78, R * .02), (R * .50, R * .14)]; out.append(np.array([(u * c - v * s_, u * s_ + v * c) for u, v in spn(P, True, (2,), 5)]))
    c, s_ = math.cos(rot), math.sin(rot); return [np.c_[cx + (q[:, 0] * c - q[:, 1] * s_) * sq[0], cy + (q[:, 0] * s_ + q[:, 1] * c) * sq[1]] for q in out]


def body_g1(T, li, seed=960):
    p = Part(T, (T.c[0] - T.s * 4.6, T.c[1] - T.s * 3.6, T.c[0] + T.s * 4.6, T.c[1] + T.s * 3.6), seed)
    B = p.shape([(-.8, 1.0), (-1.6, 1.3), (-2.2, 2.0), (-2.2, 4.4), (2.2, 4.4), (2.2, 2.0), (1.6, 1.3), (.8, 1.0)], C['skin'], 1.1, z=-.5); p.shade([(.2, 1.0), (.5, 2.0), (.2, 4.6), (2.6, 4.6), (2.4, 1.0)], C['sh'], B, z=-.5)
    c = T(np.array([[0., 2.35]]), -.4)[0]; [p.f.fill(q, C['sun']) for q in sunmark(c[0], c[1], T.s * .95, T.roll)]; [p.l.line(np.vstack([q, q[:1]]), .4 * p.k, INK) for q in sunmark(c[0], c[1], T.s * .95, T.roll)]
    for sd in (-1, 1):
        Q = p.shape([(sd * .86, 1.02), (sd * 1.4, 1.1), (sd * 2.2, 1.5), (sd * 2.9, 2.4), (sd * 3.2, 4.6), (sd * 1.0, 4.6), (sd * 1.15, 2.4)], C['haori'], 1.1, z=-.3, co=(0, 4, 5)); p.shade([(sd * 2.0 + .3, 1.0), (sd * 2.0 + .1, 2.4), (sd * 2.0, 4.8), (sd * 2.0 + 2.2, 4.8), (sd * 2.0 + 2.0, 1.0)], C['haoriS'], Q, z=-.3); Qt = p.shape([(sd * .86, 1.02), (sd * 1.10, 1.06), (sd * 1.38, 2.4), (sd * 1.24, 4.6), (sd * 1.0, 4.6), (sd * 1.15, 2.4)], C['trim'], .7, z=-.28, co=(0, 1, 3, 4))
    return p.done(li)


def g1(f):
    x, y = 1330, 150; t, b = g1_t(f, 5); ro = crown_roll(x, y); li = light('back', math.atan2(500 - y, 960 - x)); e = pick(EX, ('worry', 'laugh', t))
    T = Rig(x, y, 130, .08, -.06 - .05 * b, ro - .02 * b, .12, r=(.92, 1.14, .84), sx=1 - .02 * b, sy=1 + .03 * b); st = Stack(); st.add(body_g1(T, li)); return over4(st.a, draw(T, li, e, f, wind=.1 * math.sin(f // 2 * .4)))
